import datetime
import re
from dataclasses import dataclass
from decimal import Context, Decimal
from typing import Dict, Iterable, List, Optional

__all__ = [
    "Entry",
    "ParseError",
    "parse",
    "balance",
    "by_category",
    "by_month",
    "filter_entries",
]

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")

# Sums must stay exact however large the amounts are.
_EXACT = Context(prec=1000)


@dataclass(frozen=True)
class Entry:
    """One ledger line."""

    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A line of the ledger is wrong. ``line`` is its 1-based number."""

    def __init__(self, line: int, reason: str):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


def parse_date(text: str) -> datetime.date:
    """Parse ``YYYY-MM-DD`` strictly; raise ``ValueError`` when it is not a real date."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r" % text) from None


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for number, raw in enumerate(text.split("\n"), start=1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        fields = _SEPARATOR_RE.split(line, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected DATE CATEGORY AMOUNT [NOTE], got %r" % line
            )
        date_text, category, amount_text = fields[:3]
        note = fields[3].strip() if len(fields) == 4 else ""
        try:
            date = parse_date(date_text)
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        if not _AMOUNT_RE.fullmatch(amount_text):
            raise ParseError(number, "invalid amount %r" % amount_text)
        entries.append(Entry(date, category.lower(), Decimal(amount_text), note))
    return entries


def _total(amounts: Iterable[Decimal]) -> Decimal:
    total = Decimal("0")
    for amount in amounts:
        total = _EXACT.add(total, amount)
    return total


def balance(entries: Iterable[Entry]) -> Decimal:
    """Total of all amounts (zero for no entries)."""
    return _total(entry.amount for entry in entries)


def _group(entries: Iterable[Entry], key) -> Dict[str, Decimal]:
    totals = {}  # type: Dict[str, Decimal]
    for entry in entries:
        name = key(entry)
        totals[name] = _EXACT.add(totals.get(name, Decimal("0")), entry.amount)
    return totals


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per category."""
    return _group(entries, lambda entry: entry.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per month, keyed ``"YYYY-MM"``."""
    return _group(entries, lambda entry: "%04d-%02d" % (entry.date.year, entry.date.month))


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    """Entries matching all given filters, in input order. ``None`` = no filter."""
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result

