"""The ``pennywise`` command line."""

import argparse
import csv
import datetime
import io
import json
import sys
from decimal import Context, Decimal
from typing import List, Optional

from pennywise.ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
    parse_date,
)

_CENT = Decimal("0.01")
_EXACT = Context(prec=1000)


class _Failure(Exception):
    """A mistake that ends the command with ``code`` and a stderr message."""

    def __init__(self, code: int, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


# --- formatting -----------------------------------------------------------


def format_amount(amount: Decimal) -> str:
    """Exactly two decimals; zero is always ``0.00`` (never ``-0.00``)."""
    cents = _EXACT.quantize(amount, _CENT)
    if cents == 0:
        cents = abs(cents)
    return format(cents, "f")


def format_entry(entry: Entry) -> str:
    """``DATE CATEGORY AMOUNT NOTE``; the note and its space are left out when empty."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line


def _entry_dict(entry: Entry) -> dict:
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": format_amount(entry.amount),
        "note": entry.note,
    }


def _lines(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


# --- reading --------------------------------------------------------------


def _read_text(path: str) -> str:
    try:
        if path == "-":
            stream = sys.stdin
            raw = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
        else:
            with open(path, "rb") as handle:
                raw = handle.read()
        if isinstance(raw, bytes):
            raw = raw.decode("utf-8-sig")
        return raw
    except OSError as exc:
        reason = exc.strerror or str(exc)
        name = "standard input" if path == "-" else repr(path)
        raise _Failure(2, "cannot read %s: %s" % (name, reason)) from None
    except UnicodeDecodeError:
        name = "standard input" if path == "-" else repr(path)
        raise _Failure(2, "cannot read %s: not valid UTF-8" % name) from None


def _load(path: str) -> List[Entry]:
    text = _read_text(path)
    try:
        return parse(text)
    except ParseError as exc:
        raise _Failure(1, str(exc)) from None


def _sorted(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda entry: entry.date)  # stable


# --- commands -------------------------------------------------------------


def _cmd_balance(args) -> str:
    total = format_amount(balance(_load(args.file)))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args) -> str:
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(totals)
    if args.json:
        return json.dumps({name: format_amount(totals[name]) for name in names}) + "\n"
    return _lines(["%s  %s" % (name, format_amount(totals[name])) for name in names])


def _selected(args) -> List[Entry]:
    entries = _load(args.file)
    return _sorted(filter_entries(entries, args.category, args.since, args.until))


def _cmd_list(args) -> str:
    entries = _selected(args)
    if args.json:
        return json.dumps([_entry_dict(entry) for entry in entries]) + "\n"
    return _lines([format_entry(entry) for entry in entries])


def _cmd_export(args) -> str:
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for entry in _selected(args):
        row = _entry_dict(entry)
        writer.writerow([row["date"], row["category"], row["amount"], row["note"]])
    return out.getvalue()


def _cmd_add(args) -> str:
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise _Failure(1, "line 1: invalid %s %r" % (label, value))
    if args.category.startswith("#"):
        raise _Failure(1, "line 1: invalid category %r" % args.category)
    note = args.note or ""
    if "\n" in note or "\r" in note:
        raise _Failure(1, "line 1: note must not contain a newline")

    candidate = " ".join([args.date, args.category, args.amount] + ([note] if note.strip() else []))
    try:
        entries = parse(candidate)
    except ParseError as exc:
        raise _Failure(1, str(exc)) from None
    if len(entries) != 1:
        raise _Failure(1, "line 1: expected exactly one entry")
    line = format_entry(entries[0])

    try:
        payload = (line + "\n").encode("utf-8")
    except UnicodeEncodeError:
        raise _Failure(1, "line 1: entry is not valid UTF-8 text") from None

    try:
        try:
            with open(args.file, "rb") as handle:
                handle.seek(0, io.SEEK_END)
                if handle.tell() > 0:
                    handle.seek(-1, io.SEEK_END)
                    if handle.read(1) != b"\n":
                        payload = b"\n" + payload
        except FileNotFoundError:
            pass
        with open(args.file, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise _Failure(2, "cannot write %r: %s" % (args.file, exc.strerror or exc)) from None
    return line + "\n"


# --- argument parsing -----------------------------------------------------


def _date_arg(text: str) -> datetime.date:
    try:
        return parse_date(text)
    except ValueError:
        raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell where the household money went."
    )
    commands = parser.add_subparsers(dest="command", metavar="COMMAND")
    commands.required = True

    def file_arg(sub):
        sub.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")

    sub = commands.add_parser("balance", help="print the total")
    file_arg(sub)
    sub.add_argument("--json", action="store_true", help="print JSON")
    sub.set_defaults(run=_cmd_balance)

    sub = commands.add_parser("summary", help="print totals per category or month")
    file_arg(sub)
    sub.add_argument("--by", choices=["category", "month"], default="category")
    sub.add_argument("--json", action="store_true", help="print JSON")
    sub.set_defaults(run=_cmd_summary)

    def filters(sub):
        sub.add_argument("--category", metavar="C", help="only this category (any case)")
        sub.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE, inclusive")
        sub.add_argument("--until", type=_date_arg, metavar="DATE", help="up to DATE, inclusive")

    sub = commands.add_parser("list", help="print entries, oldest first")
    file_arg(sub)
    filters(sub)
    sub.add_argument("--json", action="store_true", help="print JSON")
    sub.set_defaults(run=_cmd_list)

    sub = commands.add_parser("add", help="append an entry to the ledger")
    sub.add_argument("file", metavar="FILE", help="ledger file (created if absent)")
    sub.add_argument("date", metavar="DATE")
    sub.add_argument("category", metavar="CATEGORY")
    sub.add_argument("amount", metavar="AMOUNT")
    sub.add_argument("note", metavar="NOTE", nargs="?", default="")
    sub.set_defaults(run=_cmd_add)

    sub = commands.add_parser("export", help="print entries as CSV")
    file_arg(sub)
    sub.add_argument("--format", choices=["csv"], default="csv")
    sub.set_defaults(run=_cmd_export, category=None, since=None, until=None)

    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:  # argparse: usage error (2) or --help (0)
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = args.run(args)
    except _Failure as failure:
        sys.stderr.write("pennywise: %s\n" % failure.message)
        return failure.code
    sys.stdout.write(output)
    sys.stdout.flush()
    return 0


if __name__ == "__main__":  # pragma: no cover
    sys.exit(main())

