import datetime
import unittest
from decimal import Decimal

import pennywise
from pennywise import Entry, ParseError, balance, by_category, by_month, filter_entries, parse

D = datetime.date

SAMPLE = """# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


class ParseTests(unittest.TestCase):
    def test_sample(self):
        entries = parse(SAMPLE)
        self.assertEqual(
            entries,
            [
                Entry(D(2024, 3, 1), "salary", Decimal("2500.00"), "March pay"),
                Entry(D(2024, 3, 2), "groceries", Decimal("-42.50"), "weekly shop"),
                Entry(D(2024, 3, 5), "rent", Decimal("-900"), ""),
            ],
        )
        self.assertIsInstance(entries[0].date, datetime.date)
        self.assertIsInstance(entries[0].amount, Decimal)

    def test_empty_and_ignorable(self):
        self.assertEqual(parse(""), [])
        self.assertEqual(parse("\n  \n\t\n# c\n   # indented comment\n"), [])

    def test_valid_amounts(self):
        for text, value in [("12", "12"), ("12.5", "12.5"), ("-0.99", "-0.99"),
                            ("+2500", "2500"), ("2500.00", "2500"), ("0", "0")]:
            with self.subTest(text):
                self.assertEqual(parse("2024-01-01 a " + text)[0].amount, Decimal(value))

    def test_invalid_amounts(self):
        for text in ["12.505", "1,000.00", "abc", ".5", "12.", "--1", "1e3", "٣"]:
            with self.subTest(text):
                with self.assertRaises(ParseError) as ctx:
                    parse("2024-01-01 a " + text)
                self.assertEqual(ctx.exception.line, 1)

    def test_invalid_dates(self):
        for text in ["2024-02-30", "2024-13-01", "24-01-01", "2024/01/01", "2024-1-1",
                     "2023-02-29", "2024-00-10", "x"]:
            with self.subTest(text):
                with self.assertRaises(ParseError):
                    parse(text + " a 1")

    def test_leap_day_ok(self):
        self.assertEqual(parse("2024-02-29 a 1")[0].date, D(2024, 2, 29))

    def test_too_few_fields(self):
        for text in ["2024-01-01", "2024-01-01 food", "justone"]:
            with self.subTest(text):
                with self.assertRaises(ParseError):
                    parse(text)

    def test_category_lowercased(self):
        self.assertEqual(parse("2024-01-01 RenT 1")[0].category, "rent")

    def test_separators_tabs_and_runs(self):
        e = parse("  2024-01-01\t \tfood \t -3.5 \t a  b\tc  \t")[0]
        self.assertEqual((e.category, e.amount, e.note), ("food", Decimal("-3.5"), "a  b\tc"))

    def test_note_internal_whitespace_preserved(self):
        self.assertEqual(parse("2024-01-01 a 1 x   y\t\tz")[0].note, "x   y\t\tz")

    def test_note_with_hash_is_kept(self):
        self.assertEqual(parse("2024-01-01 a 1 buy #1")[0].note, "buy #1")

    def test_crlf(self):
        entries = parse("2024-01-01 a 1 n\r\n\r\n2024-01-02 b 2\r\n")
        self.assertEqual([e.note for e in entries], ["n", ""])
        self.assertEqual(entries[1].amount, Decimal("2"))

    def test_line_numbers_count_blank_and_comment_lines(self):
        with self.assertRaises(ParseError) as ctx:
            parse("# c\n\n2024-01-01 a 1\n   \n2024-01-01 a abc\n")
        self.assertEqual(ctx.exception.line, 5)
        self.assertIn("line 5", str(ctx.exception))
        self.assertIsInstance(ctx.exception, ValueError)

    def test_error_message_format(self):
        with self.assertRaises(ParseError) as ctx:
            parse("2024-01-01 a abc")
        self.assertEqual(str(ctx.exception), "line 1: invalid amount 'abc'")

    def test_first_error_wins(self):
        with self.assertRaises(ParseError) as ctx:
            parse("bad\nworse")
        self.assertEqual(ctx.exception.line, 1)

    def test_entry_is_frozen(self):
        with self.assertRaises(Exception):
            parse("2024-01-01 a 1")[0].note = "x"

    def test_public_api(self):
        self.assertEqual(
            set(pennywise.__all__),
            {"Entry", "ParseError", "parse", "balance", "by_category", "by_month", "filter_entries"},
        )


class AggregateTests(unittest.TestCase):
    def setUp(self):
        self.entries = parse(
            "2024-03-01 salary 2500\n2024-03-02 Food -10.10\n"
            "2024-04-02 food -0.20\n2024-04-03 rent -900\n"
        )

    def test_balance(self):
        self.assertEqual(balance(self.entries), Decimal("1589.70"))
        self.assertEqual(balance([]), Decimal("0"))
        self.assertIsInstance(balance([]), Decimal)

    def test_by_category(self):
        self.assertEqual(
            by_category(self.entries),
            {"salary": Decimal("2500"), "food": Decimal("-10.30"), "rent": Decimal("-900")},
        )
        self.assertEqual(by_category([]), {})

    def test_by_month(self):
        self.assertEqual(
            by_month(self.entries),
            {"2024-03": Decimal("2489.90"), "2024-04": Decimal("-900.20")},
        )

    def test_exact_with_huge_amounts(self):
        big = "1" + "0" * 40
        entries = parse("2024-01-01 a %s\n2024-01-01 a 0.01\n" % big)
        self.assertEqual(balance(entries), Decimal(big) + Decimal("0.01"))
        self.assertEqual(by_month(entries)["2024-01"], Decimal(big) + Decimal("0.01"))


class FilterTests(unittest.TestCase):
    def setUp(self):
        self.entries = parse(
            "2024-03-05 b 1\n2024-03-01 Food 2\n2024-03-03 food 3\n2024-03-05 food 4\n"
        )

    def test_no_filter_keeps_order(self):
        self.assertEqual(filter_entries(self.entries), self.entries)
        self.assertIsNot(filter_entries(self.entries), self.entries)

    def test_category_case_insensitive(self):
        got = filter_entries(self.entries, category="FOOD")
        self.assertEqual([e.amount for e in got], [Decimal(2), Decimal(3), Decimal(4)])

    def test_since_until_inclusive(self):
        got = filter_entries(self.entries, since=D(2024, 3, 3), until=D(2024, 3, 5))
        self.assertEqual([e.amount for e in got], [Decimal(1), Decimal(3), Decimal(4)])
        got = filter_entries(self.entries, until=D(2024, 3, 1))
        self.assertEqual([e.amount for e in got], [Decimal(2)])
        got = filter_entries(self.entries, since=D(2024, 3, 5))
        self.assertEqual([e.amount for e in got], [Decimal(1), Decimal(4)])

    def test_combined(self):
        got = filter_entries(self.entries, "food", D(2024, 3, 2), D(2024, 3, 4))
        self.assertEqual([e.amount for e in got], [Decimal(3)])


if __name__ == "__main__":
    unittest.main()
