        self.assertEqual(filter_entries(self.entries), self.entries)
        self.assertIsNot(filter_entries(self.entries), self.entries)

    def test_category_case_insensitive(self):
        got = filter_entries(self.entries, category="FOOD")
        self.assertEqual([e.amount for e in got], [Decimal(2), Decimal(3), Decimal(4)])

