        got = filter_entries(self.entries, until=D(2024, 3, 1))
        self.assertEqual([e.amount for e in got], [Decimal(2)])
        got = filter_entries(self.entries, since=D(2024, 3, 5))
        self.assertEqual([e.amount for e in got], [Decimal(1), Decimal(4)])

    def test_combined(self):
        got = filter_entries(self.entries, "food", D(2024, 3, 2), D(2024, 3, 4))
        self.assertEqual([e.amount for e in got], [Decimal(3)])


